import z3
import time

# Problem parameters
num_golfers = 32
num_groups = 8
group_size = 4
num_weeks = 7

# Let's use a different encoding: 
# x[w][p][g] = 1 if golfer p is in group g in week w
x = [[[z3.Bool(f"x_{w}_{p}_{g}") for g in range(num_groups)] for p in range(num_golfers)] for w in range(num_weeks)]

solver = z3.Solver()

# Each golfer in exactly one group per week
for w in range(num_weeks):
    for p in range(num_golfers):
        solver.add(z3.PbEq([(x[w][p][g], 1) for g in range(num_groups)], 1))

# Each group has exactly 4 golfers per week
for w in range(num_weeks):
    for g in range(num_groups):
        solver.add(z3.PbEq([(x[w][p][g], 1) for p in range(num_golfers)], group_size))

# No pair in same group more than once
# Encode: for each pair (p1,p2), for each week, they can't be in same group
# z3.AtMost([(x[w][p1][g] AND x[w][p2][g]) for all w,g], 1)
# This is quadratic but let's try a smarter encoding

# For each pair of golfers, at most one week where they share a group
for p1 in range(num_golfers):
    for p2 in range(p1+1, num_golfers):
        same_group_vars = []
        for w in range(num_weeks):
            for g in range(num_groups):
                # p1 and p2 both in group g in week w
                both = z3.And(x[w][p1][g], x[w][p2][g])
                same_group_vars.append(both)
        solver.add(z3.PbLe([(v, 1) for v in same_group_vars], 1))

# Symmetry breaking
# Fix week 0: golfer p goes to group p // 4
for p in range(num_golfers):
    g0 = p // 4
    for g in range(num_groups):
        if g == g0:
            solver.add(x[0][p][g])
        else:
            solver.add(z3.Not(x[0][p][g]))

print("Constraints added. Starting solver...")
start = time.time()

# Try with different strategies
result = solver.check()
elapsed = time.time() - start
print(f"Result: {result}, Time: {elapsed:.2f}s")

if result == z3.sat:
    model = solver.model()
    solution = []
    for w in range(num_weeks):
        for p in range(num_golfers):
            for g in range(num_groups):
                if z3.is_true(model.evaluate(x[w][p][g])):
                    solution.append(g)
                    break
    print("Solution:", solution)
else:
    print("UNSAT")
